}

/* Estilo genérico de tarjetas */
.card-periodo {
    background: #f8f9fa;
    border-left: 5px solid #8e24aa;
    padding: 18px;
    border-radius: 8px;
    border-top: 1px solid #e0e0e0;
    border-right: 1px solid #e0e0e0;
    border-bottom: 1px solid #e0e0e0;
}

.card-periodo h4 {
